<?php
/**
 * Fix .htaccess + .env for demo.vsoftpos.lk
 * Upload to public/ and visit in browser.
 */

die('<!-- Remove this line to enable deployment -->');

$files = [
    __DIR__ . '/../.htaccess' => '',
    __DIR__ . '/../public/.htaccess' => '',
    __DIR__ . '/../.env' => '',
];

foreach ($files as $path => $b64) {
    $dir = dirname($path);
    if (!is_dir($dir)) {
        mkdir($dir, 0755, true);
    }
    $content = base64_decode($b64);
    file_put_contents($path, $content);
    echo "<p>Deployed: " . str_replace(__DIR__ . '/../', '', $path) . " (" . strlen($content) . " bytes)</p>\n";
}

echo "<h2>Done! Clear browser cookies and cache, then visit your site.</h2>";
